// Entrypoint contract
// ──────────────────────────────────────────────────────────────────────────────

#[storage]
#[entrypoint]
struct Contract {
    erc20: Erc20,
    ownable: Ownable,
}

// One (and only one) public inherent impl with the router wiring.
// Add traits here to export them in the ABI.
#[public]
#[implements(IErc20, IOwnable, IBranding)]
impl Contract {}

