  start_index=-1
  for index in "${!packages[@]}"; do
    if [[ "${packages[$index]}" == "$E2E_START_FROM" ]]; then
      start_index="$index"
      break
    fi
  done
  if (( start_index < 0 )); then
    echo "Unknown E2E_START_FROM package: $E2E_START_FROM" >&2
    exit 2
  fi
fi

