#[storage]
#[entrypoint]
pub struct Caller {}

#[public]
impl Caller {
    fn no_input_no_output(&self, callee_addr: Address) {
        let callee = Callee::new(callee_addr);
        callee
            .no_input_no_output(self.vm(), Call::new())
            .expect("Call failed")
    }

    fn one_input_one_output(&self, callee_addr: Address, input: U256) -> U256 {
        let callee = Callee::new(callee_addr);
        callee
            .one_input_one_output(self.vm(), Call::new(), input)
            .expect("Call failed")
    }

    fn multiple_inputs_multiple_outputs(
        &self,
        callee_addr: Address,
        input1: U256,
        input2: Address,
    ) -> (U256, bool, Address, FixedBytes<32>) {
        let callee = Callee::new(callee_addr);
        callee
            .multiple_inputs_multiple_outputs(self.vm(), Call::new(), input1, input2)
            .expect("Call failed")
    }

    fn mutable(&mut self, callee_addr: Address) -> bool {
        let callee = Callee::new(callee_addr);
        let ctx = Call::new_mutating(self);
        callee.mutable(self.vm(), ctx).expect("Call failed")
    }

    fn fails(&self, callee_addr: Address) {
        let callee = Callee::new(callee_addr);
        callee.fails(self.vm(), Call::new()).expect("Call failed")
    }

    fn outputs_result_ok(&self, callee_addr: Address) -> Result<(U256, U256), Vec<u8>> {
        let callee = Callee::new(callee_addr);
        let ret = callee.outputs_result_ok(self.vm(), Call::new());
        match ret {
            Ok((a, b)) => Ok((a, b)),
            Err(e) => Err(e.into()),
        }
    }

    fn outputs_result_err(&self, callee_addr: Address) -> Result<U256, Vec<u8>> {
        let callee = Callee::new(callee_addr);
        let ret = callee.outputs_result_err(self.vm(), Call::new());
        match ret {
            Ok(a) => Ok(a),
            Err(e) => Err(e.into()),
        }
    }

    fn outputs_arbresult_ok(&self, callee_addr: Address) -> ArbResult {
        let callee = Callee::new(callee_addr);
        callee.outputs_arbresult_ok(self.vm(), Call::new())
    }

    fn outputs_arbresult_err(&self, callee_addr: Address) -> ArbResult {
        let callee = Callee::new(callee_addr);
        callee.outputs_arbresult_err(self.vm(), Call::new())
    }
}
